  1→import React, { useState, useCallback, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import AppHeader from "@/components/AppHeader";
  5→import AuthDialog from "@/components/AuthDialog";
  6→import JobSidebar from "@/components/JobSidebar";
  7→import JobDetailView from "@/components/JobDetailView";
  8→import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
  9→import { toast } from "sonner";
 10→
 11→export interface PastJob {
 12→  id: string;
 13→  title: string | null;
 14→  job_description: string;
 15→  status: string;
 16→  created_at: string;
 17→  resume_count: number;
 18→  jd_analysis_json: any;
 19→  dynamic_weights_json: Record<string, number> | null;
 20→  inbox_email: string | null;
 21→}
 22→
 23→export interface Result {
 24→  id: string;
 25→  resume_id: string;
 26→  overall_score: number;
 27→  missing_skills: string[];
 28→  summary: string | null;
 29→  interview_questions: any;
 30→  filename: string;
 31→  file_path: string | null;
 32→  candidate_name: string | null;
 33→  candidate_email?: string | null;
 34→  candidate_phone?: string | null;
 35→  candidate_location?: string | null;
 36→  // Dynamic scoring fields
 37→  hard_fit?: boolean;
 38→  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
 39→  confidence?: number;
 40→  strengths_json?: string[];
 41→  gaps_json?: string[];
 42→  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string };
 43→  matched_must_haves?: string[];
 44→  missing_must_haves?: string[];
 45→  scoring_version?: string;
 46→  pending?: boolean;
 47→  // Parsed resume sections
 48→  experience?: any[];
 49→  education?: any[];
 50→}
 51→
 52→export interface ExistingResume {
 53→  id: string;
 54→  filename: string;
 55→  file_path: string | null;
 56→  candidate_name: string | null;
 57→  created_at: string;
 58→}
 59→
 60→const Index = () => {
 61→  const { user } = useAuth();
 62→
 63→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 64→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
 65→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
 66→  const [results, setResults] = useState<Result[]>([]);
 67→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
 68→  const [authOpen, setAuthOpen] = useState(false);
 69→
 70→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
 71→
 72→  const fetchPastJobs = useCallback(async () => {
 73→    if (!user) return;
 74→    setLoadingPastJobs(true);
 75→    try {
 76→      const { data: jobs } = await supabase
 77→        .from("jobs")
 78→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
 79→        .eq("user_id", user.id)
 80→        .order("created_at", { ascending: false })
 81→        .limit(50);
 82→      if (jobs) {
 83→        setPastJobs(jobs.map((j: any) => ({
 84→          id: j.id,
 85→          title: j.title,
 86→          job_description: j.job_description,
 87→          status: j.status,
 88→          created_at: j.created_at,
 89→          resume_count: j.resumes?.[0]?.count ?? 0,
 90→          jd_analysis_json: j.jd_analysis_json,
 91→          dynamic_weights_json: j.dynamic_weights_json,
 92→          inbox_email: j.inbox_email ?? null,
 93→        })));
 94→      }
 95→    } catch (err) {
 96→      console.error("Failed to load past jobs:", err);
 97→    } finally {
 98→      setLoadingPastJobs(false);
 99→    }
100→  }, [user]);
101→
102→  useEffect(() => {
103→    fetchPastJobs();
104→  }, [fetchPastJobs]);
105→
106→  const loadJobData = async (jobId: string) => {
107→    setSelectedJobId(jobId);
108→    try {
109→      const [resumesRes, resumeListRes] = await Promise.all([
110→        supabase
111→          .from("resumes")
112→          .select("id, filename, file_path, candidate_name, created_at")
113→          .eq("job_id", jobId)
114→          .order("created_at", { ascending: false }),
115→        supabase
116→          .from("resumes")
117→          .select("id, filename, file_path, candidate_name, parsed_json")
118→          .eq("job_id", jobId),
119→      ]);
120→
121→      const resumes = resumesRes.data ?? [];
122→      setExistingResumes(resumes);
123→
124→      const resumeData = (resumeListRes.data ?? []) as Array<{
125→        id: string;
126→        filename: string;
127→        file_path: string | null;
128→        candidate_name: string | null;
129→        parsed_json?: any;
130→      }>;
131→      if (resumeData.length === 0) {
132→        setResults([]);
133→        return;
134→      }
135→
136→      const resumeIds = resumeData.map((r) => r.id);
137→      const { data: resultData } = await supabase
138→        .from("results")
139→        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
140→        .in("resume_id", resumeIds);
141→
142→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
143→      const merged: Result[] = (resultData ?? []).map((r: any) => {
144→        const resume = resumeMap.get(r.resume_id);
145→        const parsed = resume?.parsed_json as any;
146→        return {
147→          ...r,
148→          overall_score: r.overall_score ?? 0,
149→          missing_skills: r.missing_skills ?? [],
150→          filename: resume?.filename ?? "Unknown",
151→          file_path: resume?.file_path ?? null,
152→          candidate_name: resume?.candidate_name ?? null,
153→          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
154→          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
155→          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
156→          experience: parsed?.experience ?? parsed?.work_experience ?? parsed?.work_history ?? [],
157→          education: parsed?.education ?? parsed?.education_history ?? [],
158→        };
159→      });
160→      merged.sort((a, b) => b.overall_score - a.overall_score);
161→      setResults(merged);
162→    } catch (err) {
163→      console.error("Failed to load job data:", err);
164→      toast.error("Failed to load job data");
165→    }
166→  };
167→
168→  const handleNewJob = () => {
169→    setSelectedJobId(null);
170→    setResults([]);
171→    setExistingResumes([]);
172→  };
173→
174→  const handleJobCreated = (job: PastJob) => {
175→    setPastJobs((prev) => [job, ...prev]);
176→    setSelectedJobId(job.id);
177→    loadJobData(job.id);
178→  };
179→
180→  const handleRenameJob = (jobId: string, newTitle: string) => {
181→    setPastJobs((prev) =>
182→      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
183→    );
184→  };
185→
186→  const handleDeleteJob = async (jobId: string) => {
187→    try {
188→      await supabase.from("resumes").delete().eq("job_id", jobId);
189→      await supabase.from("jobs").delete().eq("id", jobId);
190→      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
191→      if (selectedJobId === jobId) handleNewJob();
192→      toast.success("Job deleted");
193→    } catch {
194→      toast.error("Failed to delete job");
195→    }
196→  };
197→
198→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
199→    setPastJobs((prev) =>
200→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
201→    );
202→  };
203→
204→  const requireAuth = useCallback(() => {
205→    if (!user) { setAuthOpen(true); return true; }
206→    return false;
207→  }, [user]);
208→
209→  return (
210→    <SidebarProvider className="h-svh overflow-hidden">
211→      <JobSidebar
212→        pastJobs={pastJobs}
213→        selectedJobId={selectedJobId}
214→        loadingPastJobs={loadingPastJobs}
215→        onSelectJob={loadJobData}
216→        onNewJob={handleNewJob}
217→        onRenameJob={handleRenameJob}
218→        onDeleteJob={handleDeleteJob}
219→        onAuthRequired={() => setAuthOpen(true)}
220→        isAuthenticated={!!user}
221→      />
222→
223→      <SidebarInset className="h-svh overflow-y-auto">
224→        <AppHeader />
225→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
226→          <SidebarTrigger />
227→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
228→        </div>
229→        <JobDetailView
230→          selectedJobId={selectedJobId}
231→          selectedJob={selectedJob}
232→          results={results}
233→          setResults={setResults}
234→          existingResumes={existingResumes}
235→          setExistingResumes={setExistingResumes}
236→          onJobCreated={handleJobCreated}
237→          onAuthRequired={() => setAuthOpen(true)}
238→          isAuthenticated={!!user}
239→          onJobUpdated={handleJobUpdated}
240→        />
241→      </SidebarInset>
242→
243→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
244→    </SidebarProvider>
245→  );
246→};
247→
248→export default Index;
